Healthchecks.ejemplo:
startupProbe:
  httpGet: { path: /healthz, port: 8080 }
  failureThreshold: 30
readinessProbe:
  httpGet: { path: /readyz, port: 8080 }
  periodSeconds: 5
livenessProbe:
  httpGet: { path: /healthz, port: 8080 }
  periodSeconds: 10
  failureThreshold: 3

Istio - Linkerd.ejemplo:
apiVersion: networking.istio.io/v1
kind: VirtualService
metadata: { name: pagos-ruta }
spec:
  hosts: [pagos]
  http:
  - route:
    - { destination: { host: pagos, subset: v1 }, weight: 90 }
    - { destination: { host: pagos, subset: v2 }, weight: 10 }

Kubernetes.ejemplo:
apiVersion: apps/v1
kind: Deployment
metadata: { name: api }
spec:
  replicas: 3
  selector: { matchLabels: { app: api } }
  template:
    metadata: { labels: { app: api } }
    spec:
      containers: [{ name: api, image: mi-org/api:1.0, ports: [{ containerPort: 8080 }] }]

nginx.ejemplo:
upstream backend { server api1:8080; server api2:8080; }
server {
  listen 80;
  location /api/ {
    proxy_pass http://backend;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  }
}
